function isValid(lease, now){
  if (lease.revoked) return false;
  const expiry = lease.issuedAt + lease.ttlSeconds;
  return now >= lease.issuedAt && now < expiry;
}
// Each lease: issuedAt=1000, ttlSeconds=3600 -> expiry=4600.
const checks = [
  { name: 'fresh',   now: 2000, revoked: false }, // before expiry
  { name: 'expired', now: 5000, revoked: false }, // past expiry
  { name: 'edge',    now: 4600, revoked: false }, // exactly at expiry -> excluded
  { name: 'revoked', now: 2000, revoked: true  }  // revoked beats time
];
for (const c of checks) {
  const lease = { issuedAt: 1000, ttlSeconds: 3600, revoked: c.revoked };
  console.log(c.name + ': ' + isValid(lease, c.now));
}
